# -*- coding: utf-8 -*-
"""Bổ sung Quyển 2 - Chương 3 (Lý thuyết phân tách lược đồ, bảo toàn thông tin & phụ thuộc hàm)."""

MCQ = [
    ("medium", r"Cho $R(A,B,C)$, $F = \{A \to B\}$ và phép tách $\rho = \{R_1(A,B),\ R_2(A,C)\}$. Phép tách này:",
     [r"Bảo toàn thông tin, vì $R_1 \cap R_2 = A$ và $A \to B = R_1 - R_2$", r"Không bảo toàn thông tin", r"Chỉ bảo toàn thông tin khi $C \to A$", r"Không xác định được"],
     "A", r"Điều kiện bảo toàn thông tin cho phép tách đôi: $R_1 \cap R_2 \to R_1 - R_2$ hoặc $R_1 \cap R_2 \to R_2 - R_1$."),
    ("medium", r"Cho $R(A,B,C)$, $F = \{A \to B\}$ và phép tách $\rho = \{R_1(A,B),\ R_2(B,C)\}$. Phép tách này:",
     [r"Bảo toàn thông tin vì $B$ là thuộc tính chung", r"Không bảo toàn thông tin vì $B \to A$ và $B \to C$ đều không suy ra từ $F$", r"Bảo toàn thông tin vì $A \to B$", r"Luôn bảo toàn vì $R_1 \cup R_2 = R$"],
     "B", r"$R_1 \cap R_2 = B$; $B^+ = B$ nên không xác định $A$ hay $C$. Phép nối có thể sinh bộ giả."),
    ("medium", r"Bộ giả (spurious tuple) là gì?",
     [r"Bộ có giá trị `NULL`", r"Bộ xuất hiện trong kết quả phép nối các quan hệ con nhưng không thuộc quan hệ gốc", r"Bộ bị mất khi phân tách", r"Bộ trùng lặp trong quan hệ gốc"],
     "B", r"Bộ giả là dấu hiệu phép tách không bảo toàn thông tin."),
    ("medium", r"Phép tách $\rho$ của $R$ bảo toàn tập phụ thuộc hàm $F$ khi:",
     [r"Mỗi phụ thuộc hàm của $F$ nằm trọn vẹn trong ít nhất một quan hệ con", r"$F \subseteq \big(\bigcup_i \pi_{R_i}(F)\big)^+$, tức hợp các hình chiếu của $F$ suy ra được mọi phụ thuộc hàm của $F$", r"$R_i \cap R_j = \emptyset$ với mọi $i, j$", r"Mỗi quan hệ con có đúng một khóa"],
     "B", r"Định nghĩa chuẩn: hợp các hình chiếu suy ra $F$. Ý A là điều kiện đủ nhưng không cần thiết."),
    ("medium", r"Bảng chase kiểm tra phép tách $R$ ($n$ thuộc tính) thành $k$ lược đồ con có kích thước:",
     [r"$n$ dòng, $k$ cột", r"$k$ dòng, $n$ cột", r"$k \times k$", r"$n \times n$"],
     "B", r"Mỗi dòng ứng với một lược đồ con $R_i$; mỗi cột ứng với một thuộc tính của $R$."),
    ("medium", r"$R(A,B,C,D)$, $F = \{A \to B,\ C \to D\}$, $\rho = \{R_1(A,B),\ R_2(C,D)\}$. Phát biểu đúng là:",
     [r"Bảo toàn thông tin và bảo toàn phụ thuộc hàm", r"Bảo toàn thông tin nhưng không bảo toàn phụ thuộc hàm", r"Không bảo toàn thông tin, nhưng bảo toàn phụ thuộc hàm", r"Không bảo toàn cả hai"],
     "C", r"$R_1 \cap R_2 = \emptyset$ nên phép nối là tích Descartes (mất thông tin về liên kết). Cả $A \to B$ và $C \to D$ đều nằm trong các quan hệ con nên được bảo toàn."),
    ("medium", r"Hình chiếu của $F$ lên $R_i$, $\pi_{R_i}(F)$, gồm:",
     [r"Mọi phụ thuộc hàm của $F$ có vế trái nằm trong $R_i$", r"Các phụ thuộc hàm $X \to Y \in F^+$ mà $XY \subseteq R_i$", r"Chỉ các phụ thuộc hàm tầm thường", r"Chỉ các khóa của $R_i$"],
     "B", r"Phải xét bao đóng $F^+$ chứ không chỉ $F$, vì phụ thuộc hàm trên $R_i$ có thể suy ra qua thuộc tính ngoài $R_i$."),
    ("medium", r"Hợp các lược đồ con $R_1 \cup R_2 \cup \cdots \cup R_k$ trong một phép tách hợp lệ của $R$ phải:",
     [r"Là tập con thực sự của $R$", r"Bằng $R$", r"Lớn hơn $R$", r"Không liên quan đến $R$"],
     "B", r"Một phép tách phải bao phủ mọi thuộc tính của $R$."),
    ("medium", r"Thuật toán bảng chase kết luận phép tách bảo toàn thông tin khi:",
     [r"Mọi dòng đều chứa ký hiệu $b$", r"Có ít nhất một dòng gồm toàn ký hiệu phân biệt $a_j$ sau khi áp dụng các phụ thuộc hàm", r"Bảng có hai dòng giống nhau", r"Bảng không thay đổi"],
     "B", r"Dòng toàn $a$ chứng tỏ một bộ gốc được khôi phục bằng phép nối, nghĩa là bảo toàn thông tin."),
    ("medium", r"$R(A,B,C)$, $F = \{A \to B,\ B \to C\}$, $\rho = \{R_1(A,B),\ R_2(B,C)\}$. Kết luận đúng là:",
     [r"Không bảo toàn thông tin", r"Bảo toàn thông tin và bảo toàn phụ thuộc hàm", r"Chỉ bảo toàn phụ thuộc hàm", r"Chỉ bảo toàn thông tin"],
     "B", r"$R_1 \cap R_2 = B \to C = R_2 - R_1$ (lossless); $A \to B \in R_1$, $B \to C \in R_2$ (preserving)."),
    ("medium", r"Trong thiết kế CSDL, tính chất nào của phép tách là BẮT BUỘC (không được vi phạm)?",
     [r"Bảo toàn phụ thuộc hàm", r"Bảo toàn thông tin (lossless join)", r"Mỗi quan hệ con có đúng hai thuộc tính", r"Tất cả quan hệ con có cùng khóa"],
     "B", r"Mất thông tin làm dữ liệu sai lệch sau khi nối; còn bảo toàn phụ thuộc hàm là mong muốn nhưng đôi khi phải đánh đổi."),
    ("medium", r"Nếu một phép tách KHÔNG bảo toàn phụ thuộc hàm thì hệ quả thực tế là:",
     [r"Mất dữ liệu ngay lập tức", r"Muốn kiểm tra phụ thuộc hàm bị mất phải nối các bảng lại, tốn chi phí", r"Không thể truy vấn được", r"Khóa chính bị xóa"],
     "B", r"Phụ thuộc hàm xuyên các quan hệ con không thể thực thi bằng khóa/ràng buộc cục bộ mà phải kiểm tra qua phép nối."),

    ("hard", r"$R(A,B,C,D)$, $F = \{A \to B,\ B \to C,\ C \to D\}$, $\rho = \{AB,\ BC,\ CD\}$. Kết quả bảng chase và việc bảo toàn phụ thuộc hàm là:",
     [r"Không bảo toàn thông tin, không bảo toàn $F$", r"Bảo toàn thông tin nhưng không bảo toàn $F$", r"Không bảo toàn thông tin nhưng bảo toàn $F$", r"Bảo toàn thông tin và bảo toàn $F$"],
     "D", r"Chase: $B \to C$ cho $b_{13} := a_3$; $C \to D$ cho $b_{14}, b_{24} := a_4$; dòng 1 thành $a_1a_2a_3a_4$. Mỗi phụ thuộc hàm của $F$ nằm trong một quan hệ con nên được bảo toàn."),
    ("hard", r"$R(A,B,C)$, $F = \{AB \to C,\ C \to B\}$, $\rho = \{R_1(A,C),\ R_2(B,C)\}$. Phát biểu đúng là:",
     [r"Bảo toàn thông tin nhưng không bảo toàn $AB \to C$", r"Không bảo toàn thông tin nhưng bảo toàn $F$", r"Bảo toàn cả hai", r"Không bảo toàn cả hai"],
     "A", r"$R_1 \cap R_2 = C \to B = R_2 - R_1$ nên lossless. Hình chiếu: $\pi_{R_1}(F)$ tầm thường, $\pi_{R_2}(F) = \{C \to B\}$; từ $C \to B$ không suy ra $AB \to C$ nên không bảo toàn."),
    ("hard", r"Định lý (Heath/Delobel): $R$ tách đôi thành $R_1, R_2$ bảo toàn thông tin khi:",
     [r"$R_1 \cap R_2$ là siêu khóa của $R_1$ hoặc của $R_2$ (trong phạm vi $F^+$)", r"$R_1 \cap R_2 = \emptyset$", r"$R_1 \subseteq R_2$", r"$R_1$ và $R_2$ có cùng số thuộc tính"],
     "A", r"Điều kiện tương đương: $R_1 \cap R_2 \to R_1$ hoặc $R_1 \cap R_2 \to R_2$ thuộc $F^+$."),
    ("hard", r"Nếu $\{R_1, R_2\}$ là phép tách bảo toàn thông tin của $R$ và $\{R_{11}, R_{12}\}$ là phép tách bảo toàn thông tin của $R_1$ (theo $\pi_{R_1}(F)$), thì $\{R_{11}, R_{12}, R_2\}$:",
     [r"Chắc chắn mất thông tin", r"Bảo toàn thông tin của $R$ (tính bắc cầu của bảo toàn thông tin)", r"Chỉ bảo toàn khi $R_{11} = R_{12}$", r"Không xét được"],
     "B", r"Tách lần lượt từng bước bảo toàn thông tin thì toàn bộ phép tách bảo toàn thông tin."),
    ("hard", r"$R(A,B,C,D)$, $F = \{A \to B,\ C \to D\}$, $\rho = \{AB,\ CD\}$. Ví dụ này minh họa điều gì?",
     [r"Phép tách bảo toàn thông tin nhưng không bảo toàn $F$", r"Phép tách bảo toàn $F$ nhưng không bảo toàn thông tin", r"Phép tách bảo toàn cả hai", r"Không phải phép tách"],
     "B", r"Mỗi phụ thuộc hàm nằm trọn trong một quan hệ con nhưng không có thuộc tính chung nên phép nối là tích Descartes."),
    ("hard", r"$R = \{(a_1,b_1,c_1),\ (a_2,b_1,c_2)\}$ trên $(A,B,C)$, tách thành $R_1(A,B)$ và $R_2(B,C)$. Số bộ giả khi nối lại là:",
     [r"0", r"1", r"2", r"4"],
     "C", r"$R_1 \bowtie R_2$ có $2 \times 2 = 4$ bộ (vì cùng $b_1$); gồm 2 bộ gốc và 2 bộ giả $(a_1,b_1,c_2)$, $(a_2,b_1,c_1)$."),
    ("hard", r"$R(A,B,C,D)$, $F = \{A \to B\}$, $\rho = \{R_1(A,C),\ R_2(B,D)\}$. Bảng chase cho kết quả:",
     [r"Có dòng toàn ký hiệu $a$ nên bảo toàn thông tin", r"Không dòng nào toàn $a$ nên không bảo toàn thông tin", r"Bảng rỗng", r"Không áp dụng được chase"],
     "B", r"Hai dòng không có thuộc tính chung ($R_1 \cap R_2 = \emptyset$); $A \to B$ không gộp được dòng nào, nên không dòng nào toàn $a$."),
    ("hard", r"$R(A,B,C,D)$, $F = \{A \to B,\ B \to C,\ C \to D\}$, $\rho = \{AB,\ AC,\ AD\}$. Phát biểu đúng là:",
     [r"Bảo toàn thông tin nhưng không bảo toàn $F$", r"Bảo toàn cả hai", r"Không bảo toàn thông tin", r"Bảo toàn $F$ nhưng không bảo toàn thông tin"],
     "A", r"Chase: $A \to B$ rồi $B \to C$, $C \to D$ cho dòng toàn $a$ (lossless). Hợp hình chiếu chỉ gồm $A \to B, A \to C, A \to D$; từ đó không suy ra $B \to C$ nên không bảo toàn $F$."),
]

SHORT = [
    (r"Kiểm tra phép tách $R(A,B,C,D,E)$ thành $R_1(A,B,C)$, $R_2(C,D,E)$ với $F = \{C \to D,\ D \to E\}$ có bảo toàn thông tin không.",
     r"$R_1 \cap R_2 = \{C\}$; $C^+ = \{C,D,E\} \supseteq R_2$, tức $C \to R_2 - R_1 = DE$. Vậy phép tách bảo toàn thông tin.",
     r"Chỉ cần $R_1 \cap R_2$ xác định hàm cho một trong hai phần."),
    (r"Tính hình chiếu của $F = \{A \to B,\ B \to C\}$ lên $R_1(A,C)$.",
     r"$A^+ = \{A,B,C\}$ nên $A \to C$ (qua $B$); $C^+ = \{C\}$. Vậy $\pi_{R_1}(F) = \{A \to C\}$.",
     r"Phải dùng bao đóng $F^+$ chứ không chỉ liệt kê phụ thuộc hàm gốc."),
    (r"Cho ví dụ chứng tỏ phép tách $R(\text{MaSV}, \text{Lop}, \text{GV})$ thành $(\text{MaSV}, \text{Lop})$ và $(\text{Lop}, \text{GV})$ có thể sinh bộ giả nếu `Lop` không xác định `GV` hay `MaSV`.",
     r"Giả sử `R = {(s1, L1, g1), (s2, L1, g2)}` (cùng lớp L1 nhưng hai giáo viên khác nhau). Nối lại cho 4 bộ, gồm `(s1, L1, g2)` và `(s2, L1, g1)` là bộ giả.",
     r"Khi `Lop` không là khóa của quan hệ con nào, phép nối sinh bộ giả."),
]

ESSAY = [
    (r"Kiểm tra tính bảo toàn thông tin bằng bảng chase và sửa phép tách",
     r"Cho $R(A,B,C,D,E)$ với $F = \{A \to B,\ B \to C,\ D \to E\}$. a) Dùng bảng chase kiểm tra phép tách $\rho_1 = \{AB, BC, DE\}$; b) Chỉ ra nguyên nhân nếu mất thông tin và đề xuất $\rho_2$ bảo toàn thông tin; c) Kiểm tra $\rho_2$ có bảo toàn phụ thuộc hàm không.",
     [r"Bước 1 - Bảng chase của $\rho_1$: dòng $AB$: $a_1\ a_2\ b_{13}\ b_{14}\ b_{15}$; dòng $BC$: $b_{21}\ a_2\ a_3\ b_{24}\ b_{25}$; dòng $DE$: $b_{31}\ b_{32}\ b_{33}\ a_4\ a_5$.",
      r"Bước 2 - Áp dụng $F$: $B \to C$ làm $b_{13} := a_3$ (hai dòng đầu cùng $a_2$ ở cột $B$). $A \to B$ và $D \to E$ không gộp thêm được dòng nào. Không có dòng toàn $a$ $\Rightarrow$ $\rho_1$ KHÔNG bảo toàn thông tin.",
      r"Bước 3 - Nguyên nhân: khóa của $R$ là $AD$ (vì $A, D$ không xuất hiện ở vế phải và $(AD)^+ = ABCDE$) nhưng không có quan hệ con nào chứa $AD$, nên không liên kết được hai nhóm $(A,B,C)$ và $(D,E)$.",
      r"Bước 4 - Sửa: $\rho_2 = \{AB, BC, DE, AD\}$. Dòng $AD$: $a_1\ b_{42}\ b_{43}\ a_4\ b_{45}$. Chase: $A \to B$ cho $b_{42} := a_2$; $B \to C$ cho $b_{43} := a_3$; $D \to E$ cho $b_{45} := a_5$. Dòng 4 thành $a_1a_2a_3a_4a_5$ $\Rightarrow$ bảo toàn thông tin.",
      r"Bước 5 - Bảo toàn $F$: $A \to B$ nằm trong $AB$, $B \to C$ trong $BC$, $D \to E$ trong $DE$ nên $\rho_2$ bảo toàn $F$.",
      r"Kết luận: $\rho_1$ mất thông tin, $\rho_2$ bảo toàn đồng thời thông tin và phụ thuộc hàm."]),
]
